local Players = game:GetService("Players") local UserInputService = game:GetService("UserInputService") local RunService = game:GetService("RunService") local CoreGui = game:GetService("CoreGui") local LocalPlayer = Players.LocalPlayer local Character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait() local Humanoid = Character:WaitForChild("Humanoid") local RootPart = Character:WaitForChild("HumanoidRootPart") local flyEnabled = false local flyConnection = nil local flySpeed = 50 local noclipEnabled = false local noclipConnection = nil local infJumpEnabled = false local infJumpConnection = nil local discordStatusEnabled = true local antiCheatEnabled = false local gui = Instance.new("ScreenGui") gui.Name = "InfinityHackGUI" gui.ResetOnSpawn = false gui.Parent = CoreGui gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling local labelFrame = Instance.new("Frame") labelFrame.Name = "InfinityLabel" labelFrame.Size = UDim2.new(0, 220, 0, 50) labelFrame.Position = UDim2.new(1, -230, 0, 15) labelFrame.BackgroundColor3 = Color3.fromRGB(20, 20, 20) labelFrame.BackgroundTransparency = 0.2 labelFrame.BorderSizePixel = 0 labelFrame.Active = true labelFrame.Draggable = true local corner = Instance.new("UICorner") corner.CornerRadius = UDim.new(0, 15) corner.Parent = labelFrame local labelText = Instance.new("TextLabel") labelText.Name = "LabelText" labelText.Size = UDim2.new(1, 0, 1, 0) labelText.BackgroundTransparency = 1 labelText.Text = "Infinity Hack 1.0" labelText.TextColor3 = Color3.fromRGB(255, 255, 255) labelText.TextScaled = true labelText.Font = Enum.Font.GothamBold labelText.Parent = labelFrame labelFrame.Parent = gui local consoleFrame = Instance.new("Frame") consoleFrame.Name = "ConsoleFrame" consoleFrame.Size = UDim2.new(0.85, 0, 1, 0) consoleFrame.Position = UDim2.new(0.075, 0, 0, 0) consoleFrame.BackgroundColor3 = Color3.fromRGB(25, 25, 25) consoleFrame.BackgroundTransparency = 0.4 consoleFrame.BorderSizePixel = 0 consoleFrame.Visible = false consoleFrame.Active = true local consoleCorner = Instance.new("UICorner") consoleCorner.CornerRadius = UDim.new(0, 0) consoleCorner.Parent = consoleFrame local backgroundOverlay = Instance.new("Frame") backgroundOverlay.Name = "Overlay" backgroundOverlay.Size = UDim2.new(1, 0, 1, 0) backgroundOverlay.BackgroundColor3 = Color3.fromRGB(0, 0, 0) backgroundOverlay.BackgroundTransparency = 0.6 backgroundOverlay.BorderSizePixel = 0 backgroundOverlay.Visible = false backgroundOverlay.Parent = gui backgroundOverlay.ZIndex = 0 local consoleTitle = Instance.new("TextLabel") consoleTitle.Size = UDim2.new(1, 0, 0, 45) consoleTitle.Position = UDim2.new(0, 0, 0, 0) consoleTitle.BackgroundColor3 = Color3.fromRGB(40, 40, 40) consoleTitle.BackgroundTransparency = 0.3 consoleTitle.Text = "Infinity Console 1.0" consoleTitle.TextColor3 = Color3.fromRGB(220, 220, 220) consoleTitle.TextScaled = true consoleTitle.Font = Enum.Font.GothamSemibold consoleTitle.ZIndex = 2 consoleTitle.Parent = consoleFrame local logArea = Instance.new("ScrollingFrame") logArea.Name = "LogArea" logArea.Size = UDim2.new(1, -30, 1, -110) logArea.Position = UDim2.new(0, 15, 0, 55) logArea.BackgroundColor3 = Color3.fromRGB(0, 0, 0) logArea.BackgroundTransparency = 1 logArea.BorderSizePixel = 0 logArea.CanvasSize = UDim2.new(0, 0, 0, 0) logArea.ScrollBarThickness = 8 logArea.AutomaticCanvasSize = Enum.AutomaticSize.Y logArea.ZIndex = 2 logArea.ScrollBarImageColor3 = Color3.fromRGB(255, 255, 255) logArea.ScrollBarImageTransparency = 0.5 local logList = Instance.new("UIListLayout") logList.Parent = logArea logList.Padding = UDim.new(0, 6) logList.HorizontalAlignment = Enum.HorizontalAlignment.Left local function addOutput(text) local line = Instance.new("TextLabel") line.Size = UDim2.new(1, -15, 0, 24) line.BackgroundTransparency = 1 line.Text = "[" .. os.date("%H:%M:%S") .. "] " .. text line.TextColor3 = Color3.fromRGB(180, 255, 180) line.TextXAlignment = Enum.TextXAlignment.Left line.Font = Enum.Font.Code line.TextSize = 18 line.RichText = true line.ZIndex = 3 line.Parent = logArea task.wait() logArea.CanvasPosition = Vector2.new(0, logArea.CanvasSize.Y.Offset) end local inputPanel = Instance.new("Frame") inputPanel.Name = "InputPanel" inputPanel.Size = UDim2.new(1, -30, 0, 60) inputPanel.Position = UDim2.new(0, 15, 1, -70) inputPanel.BackgroundColor3 = Color3.fromRGB(40, 40, 40) inputPanel.BackgroundTransparency = 0.3 inputPanel.BorderSizePixel = 0 inputPanel.ZIndex = 2 local panelCorner = Instance.new("UICorner") panelCorner.CornerRadius = UDim.new(0, 10) panelCorner.Parent = inputPanel local commandBox = Instance.new("TextBox") commandBox.Name = "CommandBox" commandBox.Size = UDim2.new(1, -20, 1, -10) commandBox.Position = UDim2.new(0, 10, 0, 5) commandBox.BackgroundColor3 = Color3.fromRGB(20, 20, 20) commandBox.BackgroundTransparency = 0.3 commandBox.PlaceholderText = "Enter command..." commandBox.Text = "" commandBox.TextColor3 = Color3.fromRGB(255, 255, 255) commandBox.ClearTextOnFocus = false commandBox.TextXAlignment = Enum.TextXAlignment.Left commandBox.Font = Enum.Font.Code commandBox.TextSize = 20 commandBox.ZIndex = 3 local commandCorner = Instance.new("UICorner") commandCorner.CornerRadius = UDim.new(0, 8) commandCorner.Parent = commandBox logArea.Parent = consoleFrame inputPanel.Parent = consoleFrame commandBox.Parent = inputPanel consoleTitle.Parent = consoleFrame consoleFrame.Parent = gui local function setFly(state, speed) if state == "enable" then if flyEnabled then addOutput("[FLY] already enabled") return end flyEnabled = true flySpeed = math.min(tonumber(speed) or 50, 1000) local bodyVelocity = Instance.new("BodyVelocity") bodyVelocity.Name = "FlyVelocity" bodyVelocity.MaxForce = Vector3.new(4000, 4000, 4000) bodyVelocity.P = 1250 bodyVelocity.Velocity = Vector3.new(0, 0, 0) flyConnection = RunService.RenderStepped:Connect(function() if not flyEnabled or not RootPart or not RootPart.Parent then if bodyVelocity then bodyVelocity:Destroy() end return end local moveDirection = Vector3.new(0, 0, 0) local camera = workspace.CurrentCamera if UserInputService:IsKeyDown(Enum.KeyCode.W) then moveDirection = moveDirection + camera.CFrame.LookVector * flySpeed end if UserInputService:IsKeyDown(Enum.KeyCode.S) then moveDirection = moveDirection - camera.CFrame.LookVector * flySpeed end if UserInputService:IsKeyDown(Enum.KeyCode.A) then moveDirection = moveDirection - camera.CFrame.RightVector * flySpeed end if UserInputService:IsKeyDown(Enum.KeyCode.D) then moveDirection = moveDirection + camera.CFrame.RightVector * flySpeed end if UserInputService:IsKeyDown(Enum.KeyCode.Space) then moveDirection = moveDirection + Vector3.new(0, flySpeed, 0) end if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then moveDirection = moveDirection - Vector3.new(0, flySpeed, 0) end bodyVelocity.Velocity = moveDirection bodyVelocity.Parent = RootPart end) addOutput("[FLY] enabled " .. flySpeed) elseif state == "disable" then if not flyEnabled then addOutput("[FLY] already disabled") return end if flyConnection then flyConnection:Disconnect() flyConnection = nil end local bodyVelocity = RootPart:FindFirstChild("FlyVelocity") if bodyVelocity then bodyVelocity:Destroy() end flyEnabled = false addOutput("[FLY] disabled") end end local function setNoclip(state) if state == "enable" then if noclipEnabled then addOutput("[NOCLIP] already enabled") return end noclipEnabled = true noclipConnection = RunService.Stepped:Connect(function() if not noclipEnabled or not Character then return end for _, part in pairs(Character:GetChildren()) do if part:IsA("BasePart") then part.CanCollide = false end end end) addOutput("[NOCLIP] enabled") elseif state == "disable" then if not noclipEnabled then addOutput("[NOCLIP] already disabled") return end if noclipConnection then noclipConnection:Disconnect() noclipConnection = nil end noclipEnabled = false addOutput("[NOCLIP] disabled") end end local function setInfJump(state) if state == "enable" then if infJumpEnabled then addOutput("[INFJUMP] already enabled") return end infJumpEnabled = true infJumpConnection = UserInputService.JumpRequest:Connect(function() if infJumpEnabled and Humanoid and Humanoid.Parent then Humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end end) addOutput("[INFJUMP] enabled") elseif state == "disable" then if not infJumpEnabled then addOutput("[INFJUMP] already disabled") return end if infJumpConnection then infJumpConnection:Disconnect() infJumpConnection = nil end infJumpEnabled = false addOutput("[INFJUMP] disabled") end end local function setAntiCheat(state) if state == "enable" then if antiCheatEnabled then addOutput("[ANTICHEAT] already enabled") return end antiCheatEnabled = true addOutput("[ANTICHEAT] enabled") elseif state == "disable" then if not antiCheatEnabled then addOutput("[ANTICHEAT] already disabled") return end antiCheatEnabled = false addOutput("[ANTICHEAT] disabled") end end local function setDiscordStatus(state) if state == "enable" then if discordStatusEnabled then addOutput("[DISCORD] already enabled") return end discordStatusEnabled = true labelText.Text = "Infinity Hack 1.0 [DC]" addOutput("[DISCORD] status set") elseif state == "disable" then if not discordStatusEnabled then addOutput("[DISCORD] already disabled") return end discordStatusEnabled = false labelText.Text = "Infinity Hack 1.0" addOutput("[DISCORD] status disabled") end end local function setSpeed(value) local newSpeed = tonumber(value) if not newSpeed then addOutput("[SPEED] current speed: " .. flySpeed) return end flySpeed = math.min(newSpeed, 1000) addOutput("[SPEED] set to " .. flySpeed) end local function executeCommand(input) if input == "" or input == nil then return end local args = {} for word in input:gmatch("%S+") do table.insert(args, word:lower()) end local command = args[1] local subCommand = args[2] local extraArg = args[3] if command == "fly" then setFly(subCommand, extraArg) elseif command == "noclip" then setNoclip(subCommand) elseif command == "infjump" then setInfJump(subCommand) elseif command == "anticheat-blocker" then setAntiCheat(subCommand) elseif command == "discord" then setDiscordStatus(subCommand) elseif command == "speed" then setSpeed(subCommand) elseif command == "clear" then logArea:ClearAllChildren() logList.Parent = logArea addOutput("cleared") else addOutput("[ERROR] " .. command) end end commandBox.FocusLost:Connect(function(enterPressed) if enterPressed then executeCommand(commandBox.Text) commandBox.Text = "" end end) UserInputService.InputBegan:Connect(function(input, gameProcessed) if gameProcessed then return end if input.KeyCode == Enum.KeyCode.F2 then consoleFrame.Visible = not consoleFrame.Visible backgroundOverlay.Visible = consoleFrame.Visible end end) LocalPlayer.CharacterAdded:Connect(function(newChar) Character = newChar Humanoid = Character:WaitForChild("Humanoid") RootPart = Character:WaitForChild("HumanoidRootPart") if flyEnabled then setFly("disable") task.wait(0.5) setFly("enable", tostring(flySpeed)) end if noclipEnabled then setNoClip("disable") task.wait(0.5) setNoclip("enable") end end) addOutput("Infinity Hack 1.0") addOutput("Gui loaded") setDiscordStatus("enable") addOutput("Cheat seccufully loaded")
